::baseUrl(), 'free.fr') > 0) { return false; } if (function_exists('curl_version')) { $ch = curl_init(); curl_setopt($ch, CURLOPT_HEADER, 0); curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1); curl_setopt($ch, CURLOPT_URL, $url); curl_setopt($ch, CURLOPT_TIMEOUT, 5); curl_setopt($ch, CURLOPT_CONNECTTIMEOUT, 3); $url_get_contents_data = curl_exec($ch); if (curl_errno($ch)) { $url_get_contents_data = false; } } elseif ( function_exists('file_get_contents') && ini_get('allow_url_fopen') ) { $context = stream_context_create(['http' => ['timeout' => 5]]); $url_get_contents_data = @file_get_contents($url, false, $context); } elseif ( function_exists('fopen') && function_exists('stream_get_contents') && ini_get('allow_url_fopen') ) { $context = stream_context_create(['http' => ['timeout' => 5]]); $handle = fopen($url, 'r', false, $context); $url_get_contents_data = $handle ? stream_get_contents($handle) : false; } else { $url_get_contents_data = false; } return $url_get_contents_data; } public static function arraycolumn($array, $column, $sort = null) { $newArray = []; if (is_array($array) === true && $array !== []) { foreach ($array as $key => $element) { $newArray[$key] = is_array($element) ? ($element[$column] ?? null) : null; } switch ($sort) { case 'SORT_ASC': asort($newArray); break; case 'SORT_DESC': arsort($newArray); break; } } return $newArray; } public static function arrayCollumn($array, $column, $sort = null) { return (Helper::arrayColumn($array, $column, $sort)); } public static function autoBackup($folder, $filter = ['backup', 'tmp']) { $baseName = str_replace('/', '', Helper::baseUrl(false, false)); $baseName = empty($baseName) ? 'ZwiiCMS' : $baseName; $fileName = $baseName . '-backup-' . date('Y-m-d-H-i-s') . '.zip'; $zip = new \ZipArchive(); if ($zip->open($folder . $fileName, \ZipArchive::CREATE | \ZipArchive::OVERWRITE) !== true) { return false; } $directory = 'site/'; $files = new \RecursiveIteratorIterator( new \RecursiveCallbackFilterIterator( new \Recursi