take, $spacePos)); } break; } $out .= $seg; $count += $segLen; $spacePos = mb_strrpos($seg, ' '); if ($spacePos !== false) { $lastWordSafeOutLen = strlen($out) - strlen(mb_substr($seg, $spacePos)); } } if ($lastWordSafeOutLen > 0 && $count >= $target) { $out = substr($out, 0, $lastWordSafeOutLen); } while (!empty($openStack)) { $out .= '</' . array_pop($openStack) . '>'; } $out = preg_replace('/\s+/u', ' ', trim($out)); if ($start + $count < $plainLen) { $out = rtrim($out, '.,;:!? ') . '...'; } return $out; } public static function encrypt($string, $key) { $encrypted = openssl_encrypt($string, 'AES-256-CBC', $key, 0, substr(md5($key), 0, 16)); return base64_encode($encrypted); } public static function decrypt($string, $key) { $decrypted = openssl_decrypt(base64_decode($string), 'AES-256-CBC', $key, 0, substr(md5($key), 0, 16)); return $decrypted; } public static function scanDir($dir) { return array_values(Helper::getSubdirectories($dir)); } public static function getSubdirectories($dir, $basePath = '') { $subdirs = array(); $iterator = new \RecursiveIteratorIterator( new \RecursiveDirectoryIterator($dir, \RecursiveDirectoryIterator::SKIP_DOTS), \RecursiveIteratorIterator::SELF_FIRST ); $subdirs['/'] = rtrim($dir, '/') . '/'; foreach ($iterator as $file) { if ($file->isDir()) { $path = str_replace('\\', '/', $file->getPathname()); $relativePath = trim(str_replace($dir, '', $path), '/'); $key = empty($relativePath) ? '/' : '/' . $relativePath; $subdirs[$key] = rtrim($path, '/') . '/'; } } uksort($subdirs, function ($a, $b) { if ($a === '/') return -1; if ($b === '/') return 1; $depthA = substr_count($a, '/'); $depthB = substr_count($b, '/'); if ($depthA === $depthB) { return strcasecmp($a, $b); } return $depthA - $depthB; }); return $subdirs; } public static function cleanRssText($text, $isAttribute = false) { $cleanText = html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8'); if ($isAttribute) { $cleanText = htmlspecialchars($cleanText, ENT_QUOTES | ENT_HTML5, 